    padding: 0.15rem 0.5rem;
    border-radius: 4px;
    font-size: 0.75rem;
    font-weight: 600;
    margin-right: 0.5rem;
}

::deep .priority-high {
    background: #fee2e2;
    color: #dc2626;
}

::deep .priority-medium {
    background: #fef9c3;
    color: #ca8a04;
}

::deep .priority-low {
    background: #dcfce7;
    color: #16a34a;
}

::deep .task-due-date {
    font-size: 0.8rem;
    color: #6c757d;
}

::deep .task-actions {
    margin-top: 0.5rem;
    display: flex;
    gap: 0.5rem;
}

::deep .btn-move {
    padding: 0.25rem 0.5rem;
    font-size: 0.75rem;
    border: 1px solid #dee2e6;
    border-radius: 4px;
    background: #fff;
    cursor: pointer;
}

::deep .btn-move:hover {
    background: #e9ecef;
}

::deep .btn-add-task {
    width: 100%;
    padding: 0.5rem;
    margin-top: 0.75rem;
    border: 1px dashed #adb5bd;
    border-radius: 6px;
    background: transparent;
    cursor: pointer;
    color: #6c757d;
}

::deep .add-task-form {
    margin-top: 0.75rem;
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

::deep .add-task-form input,
::deep .add-task-form select {
    padding: 0.4rem 0.6rem;
    border: 1px solid #dee2e6;
    border-radius: 4px;
    font-size: 0.85rem;
}

::deep .form-actions {
    display: flex;
    gap: 0.5rem;
}

::deep .btn-save {
    padding: 0.4rem 0.8rem;
    background: #2563eb;
    color: #fff;
    border: none;
    border-radius: 4px;
    cursor: pointer;
}

::deep .btn-cancel {
    padding: 0.4rem 0.8rem;
    background: #e9ecef;
    border: none;
    border-radius: 4px;
    cursor: pointer;
}

.loading-message {
    color: #6c757d;
    font-style: italic;
}

.error-message {
    color: #dc2626;
    font-weight: 500;
}
"}

