@namespace sv_5bdf45afb4a343f1b63250778505853b.Components.Pages.Board

<div class="kanban-column">
    <div class="column-header">
        <h3>@Title (@Tasks.Count)</h3>
    </div>
    <div class="column-body">
        @foreach (var task in Tasks)
        {
            <TaskCard Task="task"
                      ShowMoveLeft="ShowMoveLeft"
                      ShowMoveRight="ShowMoveRight"
                      OnMoveLeft="() => MoveLeft(task)"
                      OnMoveRight="() => MoveRight(task)" />
        }
    </div>
    <div class="column-footer">
        <AddTaskForm OnSave="HandleAddTask" />
    </div>
</div>

@code {
    [Parameter, EditorRequired] public string Title { get; set; } = string.Empty;
    [Parameter, EditorRequired] public string Status { get; set; } = string.Empty;
    [Parameter] public List<TaskItem> Tasks { get; set; } = new();
    [Parameter] public bool ShowMoveLeft { get; set; }
    [Parameter] public bool ShowMoveRight { get; set; }
    [Parameter] public EventCallback<(TaskItem Task, string Direction)> OnMoveTask { get; set; }
    [Parameter] public EventCallback<(string Status, AddTaskForm.NewTaskModel Model)> OnAddTask { get; set; }

    private async Task MoveLeft(TaskItem task)
    {
        await OnMoveTask.InvokeAsync((task, "left"));
    }

    private async Task MoveRight(TaskItem task)
    {
        await OnMoveTask.InvokeAsync((task, "right"));
    }

    private async Task HandleAddTask(AddTaskForm.NewTaskModel model)
    {
        await OnAddTask.InvokeAsync((Status, model));
    }
}

