toolArgs.file_text:
@page "/board"
@namespace sv_5bdf45afb4a343f1b63250778505853b.Components.Pages.Board
@rendermode InteractiveServer
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

@if (isLoading)
{
    <p class="loading-message">Loading tasks...</p>
}
else if (errorMessage is not null)
{
    <p class="error-message">@errorMessage</p>
}
else
{
    <div class="board-stats">
        <span>Total: @allTasks.Count</span>
        <span>To Do: @TodoTasks.Count</span>
        <span>In Progress: @InProgressTasks.Count</span>
        <span>Done: @DoneTasks.Count</span>
        <span>Overdue: @OverdueTasks.Count</span>
    </div>

    <div class="board-search">
        <input type="text" placeholder="Search tasks..." @bind="searchText" @bind:event="oninput" />
    </div>

    <div class="kanban-board">
        <KanbanColumn Title="To Do" Status="To Do"
                      Tasks="FilteredTodoTasks"
                      ShowMoveLeft="false"
                      ShowMoveRight="true"
                      OnMoveTask="HandleMoveTask"
                      OnAddTask="HandleAddTask" />

        <KanbanColumn Title="In Progress" Status="In Progress"
                      Tasks="FilteredInProgressTasks"
                      ShowMoveLeft="true"
                      ShowMoveRight="true"
                      OnMoveTask="HandleMoveTask"
                      OnAddTask="HandleAddTask" />

        <KanbanColumn Title="Done" Status="Done"
                      Tasks="FilteredDoneTasks"
                      ShowMoveLeft="true"
                      ShowMoveRight="false"
                      OnMoveTask="HandleMoveTask"
                      OnAddTask="HandleAddTask" />
    </div>
}

@code {
    private List<TaskItem> allTasks = new();
    private string searchText = string.Empty;
    private bool isLoading = true;
    private string? errorMessage;

    private static readonly string[] ColumnOrder = { "To Do", "In Progress", "Done" };

    private List<TaskItem> TodoTasks => allTasks.Where(t => t.Status == "To Do").ToList();
    private List<TaskItem> InProgressTasks => allTasks.Where(t => t.Status == "In Progress").ToList();
    private List<TaskItem> DoneTasks => allTasks.Where(t => t.Status == "Done").ToList();
    private List<TaskItem> OverdueTasks => allTasks.Where(t => t.DueDate < DateTime.Today).ToList();

    private List<TaskItem> FilteredTodoTasks => ApplySearch(TodoTasks);
    private List<TaskItem> FilteredInProgressTasks => ApplySearch(InProgressTasks);
    private List<TaskItem> FilteredDoneTasks => ApplySearch(DoneTasks);

    private List<TaskItem> ApplySearch(List<TaskItem> tasks)
    {
        if (string.IsNullOrWhiteSpace(searchText))
            return tasks;
        return tasks.Where(t => t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase)).ToList();
    }

    protected override async Task OnInitializedAsync()
    {
        try
        {
            allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load tasks: {ex.Message}";
        }
        finally
        {
            isLoading = false;
        }
    }

    private async Task HandleMoveTask((TaskItem Task, string Direction) args)
    {
        var currentIndex = Array.IndexOf(ColumnOrder, args.Task.Status);
        var newIndex = args.Direction == "left" ? currentIndex - 1 : currentIndex + 1;

        if (newIndex < 0 || newIndex >= ColumnOrder.Length)
            return;

        var newStatus = ColumnOrder[newIndex];

        try
        {
            await TaskService.UpdateTaskStatusAsync(args.Task.Id, newStatus);
            allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to move task: {ex.Message}";
        }
    }

    private async Task HandleAddTask((string Status, AddTaskForm.NewTaskModel Model) args)
    {
        try
        {
            await TaskService.CreateTaskAsync(args.Model.Title, args.Model.Assignee, args.Model.Priority, args.Model.DueDate);
            allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to create task: {ex.Message}";
        }
    }
}

